/* 1️⃣  JavaScript – use arrow-functions & Object spread for brevity */

const users = [
  {id:1,name:'Ada',age:28},
  {id:2,name:'Bob',age:34}
];

const updateAge = (id, offset) =>
  users.map(u => (u.id===id ? {...u,age:u.age+offset} : u));

console.log(updateAge(1,5));
