# 2️⃣  Python – one‑liner comprehensions, f‑strings, context‑vars

users = [{'id':1,'name':'Ada','age':28},
         {'id':2,'name':'Bob','age':34}]

def inc_age(id, delta):
    return [{**u, 'age':u['age']+delta} if u['id']==id else u for u in users]

print(inc_age(2,2))
