// 3️⃣  Rust – use iterators, map, and the `?` error‑propagation
use std::collections::HashMap;

fn add_to_age(ages: &mut HashMap<i32,i32>, id:i32, delta:i32) -> Result<(),()> {
    ages.entry(id).and_modify(|v| *v += delta).or_insert(delta);
    Ok(())
}
